const listAuthorizedTaskBundleItems = `-- name: ListAuthorizedTaskBundleItems :many
SELECT item.id, item.workspace_id, item.bundle_id, item.ordinal, item.public_name, item.source_id, item.source_revision_id, item.tool_definition_id, item.artifact_id, item.definition_snapshot, item.invocation_plan, item.created_at
FROM agent_task_queue task
JOIN agent ON agent.id = task.agent_id AND agent.workspace_id = task.workspace_id
JOIN tool_bundle bundle
  ON bundle.id = task.tool_bundle_id AND bundle.workspace_id = task.workspace_id
JOIN tool_bundle_item item
  ON item.bundle_id = bundle.id AND item.workspace_id = bundle.workspace_id
JOIN tool_source source
  ON source.id = item.source_id AND source.workspace_id = item.workspace_id
JOIN tool_definition definition
  ON definition.id = item.tool_definition_id AND definition.workspace_id = item.workspace_id
WHERE task.id = $1
  AND task.workspace_id = $2
  AND task.agent_id = $3
  AND task.tool_bundle_id = $4
  AND task.status IN ('dispatched', 'waiting_local_directory', 'running')
  AND agent.archived_at IS NULL
  AND bundle.status = 'active'
  AND source.enabled = true
  AND definition.enabled = true
ORDER BY item.ordinal, item.id
`

type ListAuthorizedTaskBundleItemsParams struct {
	TaskID      pgtype.UUID `json:"task_id"`
	WorkspaceID pgtype.UUID `json:"workspace_id"`
	AgentID     pgtype.UUID `json:"agent_id"`
	BundleID    pgtype.Text `json:"bundle_id"`
}

func (q *Queries) ListAuthorizedTaskBundleItems(ctx context.Context, arg ListAuthorizedTaskBundleItemsParams) ([]ToolBundleItem, error) {
	rows, err := q.db.Query(ctx, listAuthorizedTaskBundleItems,
		arg.TaskID,
		arg.WorkspaceID,
		arg.AgentID,
		arg.BundleID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ToolBundleItem{}
	for rows.Next() {
		var i ToolBundleItem
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.BundleID,
			&i.Ordinal,
			&i.PublicName,
			&i.SourceID,
			&i.SourceRevisionID,
			&i.ToolDefinitionID,
			&i.ArtifactID,
			&i.DefinitionSnapshot,
			&i.InvocationPlan,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

