const pinAgentTaskToolBundle = `-- name: PinAgentTaskToolBundle :execrows
UPDATE agent_task_queue task
SET tool_bundle_id = $1
WHERE task.id = $2
  AND task.workspace_id = $3
  AND task.agent_id = $4
  AND task.tool_bundle_id IS NULL
  AND EXISTS (
      SELECT 1 FROM tool_bundle bundle
      WHERE bundle.id = $1
        AND bundle.workspace_id = task.workspace_id
        AND bundle.status = 'active'
  )
`

type PinAgentTaskToolBundleParams struct {
	BundleID    pgtype.Text `json:"bundle_id"`
	TaskID      pgtype.UUID `json:"task_id"`
	WorkspaceID pgtype.UUID `json:"workspace_id"`
	AgentID     pgtype.UUID `json:"agent_id"`
}

func (q *Queries) PinAgentTaskToolBundle(ctx context.Context, arg PinAgentTaskToolBundleParams) (int64, error) {
	result, err := q.db.Exec(ctx, pinAgentTaskToolBundle,
		arg.BundleID,
		arg.TaskID,
		arg.WorkspaceID,
		arg.AgentID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

